import { isEqual } from 'lodash-es';
import { useEffect, useState } from 'react';

import { useOverlaysEvents } from '../../../../hooks/useOverlaysEvents.js';
import { MouseCoordinate } from '../../../../types/overlays.js';

/**
 * Hook responsible to return the tooltip position
 * @param pinned - true if the tooltip is pinned state
 * @param offset - offset of the x and y axis
 * @returns Closest point to the mouse position & the x and y position of the tooltip
 */
export function useTooltipPositionHandler(
  pinned: boolean,
  offset?: { x?: number; y?: number },
): MouseCoordinate | undefined {
  const [tooltipPosition, setTooltipPosition] = useState<
    MouseCoordinate | undefined
  >();

  const {
    eventLocalPoint: mousePosition,
    isInChartBounds,
    chartBounds,
  } = useOverlaysEvents();

  useEffect(() => {
    if (!isInChartBounds || pinned || !mousePosition) {
      return;
    }

    const { x, y } = mousePosition;
    const { top: boundingTargetTop, left: boundingTargetLeft } =
      chartBounds as DOMRect;
    const newPosition = {
      x: x + boundingTargetLeft + (offset?.x ?? 0),
      y: y + boundingTargetTop + (offset?.y ?? 0),
    };
    if (!isEqual(tooltipPosition, newPosition) && isInChartBounds) {
      setTooltipPosition(newPosition);
    }
  }, [mousePosition, isInChartBounds, chartBounds, pinned, offset]);

  return tooltipPosition;
}
